<!--vbase-->
<template>
  <CodeEditor
    v-model="xsltData"
    :language="editorLanguage"
    :read-only="isReadOnly"
    :placeholder="exampleXslt"
    :wrap="wrapEnabled"
    ref="codeEditor"
  />
</template>

<script>
import beautify from 'js-beautify';
import { storeToRefs } from 'pinia';
import { defineComponent } from 'vue';
import { useDocXsltStore } from 'src/store/main';
import CodeEditor from 'src/components/common/CodeEditor.vue';

export default defineComponent({
  components: { CodeEditor },
  props: {
    formatCode: {
      type: Boolean,
      required: true,
    },
  },
  emits: ['formatComplete'],
  data() {
    return {
      exampleXslt: '',
      wrapEnabled: true,
    };
  },
  mounted() {
    this.initializeEditor();
  },
  computed: {
    xsltData: {
      get() {
        return this.current_model['xslt_data'] || '';
      },
      set(value) {
        this.current_model['xslt_data'] = value;
      },
    },
    editorLanguage() {
      return this.isJsonContent() ? 'json' : 'xml';
    },
  },
  watch: {
    formatCode(value) {
      if (value) {
        this.initFormatting();
      }
    },
  },
  methods: {
    initializeEditor() {
      this.exampleXslt = this.buildExampleXslt();
    },
    isJsonContent() {
      const trimmed = (this.current_model['xslt_data'] || '').trim();
      return (
        (trimmed.startsWith('{') && trimmed.endsWith('}')) ||
        (trimmed.startsWith('[') && trimmed.endsWith(']'))
      );
    },
    initFormatting() {
      this.wrapEnabled = false;
      if (this.isJsonContent()) {
        this.formatJsonCode();
        return;
      }
      this.formatXmlCode();
    },
    formatJsonCode() {
      try {
        this.current_model['xslt_data'] = beautify.js(
          this.current_model['xslt_data'],
          { ...this.formatOptions },
        );
        this.$emit('formatComplete', false);
      } catch (err) {
        logError('Error formatting JSON code:', err);
      }
    },
    formatXmlCode() {
      try {
        this.current_model['xslt_data'] = beautify.html(
          this.current_model['xslt_data'],
          { ...this.formatOptions },
        );
        this.$emit('formatComplete', false);
      } catch (err) {
        logError('Error formatting XML code:', err);
      }
    },
    buildExampleXslt() {
      return [
        '<?xml version="1.0" encoding="UTF-8"?>',
        '',
        '<xsl:stylesheet version="1.0" xmlns:xsl="http://www.w3.org/1999/XSL/Transform">',
        '',
        '    <xsl:output method="xml" />',
        '    <xsl:strip-space elements="*" />',
        '',
        '    <xsl:template match="/document">',
        '    <dokument>',
        '        <filename><xsl:value-of select="filename" /></filename>',
        '        <basic_info>',
        '            <invoice_number><xsl:value-of select="fields_compact/invoice_id" /></invoice_number>',
        '            <date><xsl:value-of select="fields_compact/invoice_date" /></date>',
        '        </basic_info>',
        '        <amounts>',
        '            <net_amount><xsl:value-of select="fields_compact/net_amount" /></net_amount>',
        '            <total_amount><xsl:value-of select="fields_compact/total_amount" /></total_amount>',
        '        </amounts>',
        '    </dokument>',
        '',
        '',
        '    </xsl:template>',
        '',
        '</xsl:stylesheet>',
      ].join('\n');
    },
  },
  setup() {
    const doc_xslt = useDocXsltStore();
    const { current_model, isReadOnly } = storeToRefs(doc_xslt);

    return {
      current_model,
      isReadOnly,
      formatOptions: {
        indent_size: 4,
        indent_char: ' ',
        eol: '\n',
        end_with_newline: false,
        preserve_newlines: true,
        max_preserve_newlines: 2,
        indent_inner_html: true,
        wrap_line_length: 0,
        unformatted: [],
        extra_liners: [],
      },
    };
  },
});
</script>
